#include "ksStatePackFieldsTask.h"
#include <array>
#include <iostream>
#include <stdexcept>
using T=ks::StatePackFieldsTask;void check(bool b,const char* w){if(!b)throw std::runtime_error(w);}unsigned rr(unsigned v,unsigned n){return ((v>>n)|(v<<(8-n)))&255;}unsigned rl(unsigned v,unsigned n){return ((v<<n)|(v>>(8-n)))&255;}
unsigned golden(unsigned k,const std::array<unsigned,5>& b){switch(k){case 0:return rr(rr(rr(b[0],3)|b[1],2)|b[2],3);case 1:return rr(rr(rr(rr(rr(b[0],2)|b[1],1)|b[2],1)|b[3],1)|b[4],3);case 2:return rl(rr(b[0],3)|b[1],3);case 3:return rr(rr(rr(b[0],2)|b[1],2)|b[2],4);case 4:return rr(rr(rr(rr(b[0],2)|b[1],2)|b[2],2)|b[3],2);default:return b[0]|((b[1]<<3)&127);}}
int main(){try{uint64_t cases=0;constexpr unsigned counts[]{3,5,2,3,4,2},clocks[]{92,131,71,89,107,68};constexpr unsigned offsets[6][5]={{210,209,211,0,0},{214,215,212,213,216},{217,218,0,0,0},{219,220,221,0,0},{222,223,224,225,0},{226,227,0,0,0}};for(unsigned k=0;k<6;++k)for(unsigned varying=0;varying<counts[k];++varying)for(unsigned value=0;value<256;++value)for(unsigned seed=0;seed<256;++seed){T task{T::Kind(k)};std::array<unsigned,5> bytes{};for(unsigned i=0;i<counts[k];++i)bytes[i]=i==varying?value:(seed*13+i*17)&255;unsigned reads=0,used=0;auto read=[&]()->unsigned{check(task.sourceOffset()==offsets[k][reads],"Pack late field read differs");return bytes[reads++];};while(!task.complete()){const auto c=task.nextClocks(),before=reads;check(!task.advanceBefore(c-1,read)&&before==reads,"Packing early read");check(task.advanceBefore(c,read)==c,"Packing admission differs");used+=c;}check(used==clocks[k]&&reads==counts[k],"Packing clocks/reads differ");check(task.value()==golden(k,bytes),"Packing byte/rotations/wrap differs");check(!task.advanceBefore(999,read),"Packing restarted");++cases;}
std::cout<<"PASS: "<<cases<<" whole packing recipes/all6groups/allbyte fields including out-of-range values,late observations/rotate/OR/signed reconstruction/exact clocks\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
